function Contact() {
  const config = useConfig(); const location = useLocation();
  const query = new URLSearchParams(location.search);
  const [form, setForm] = useState({ name: '', business: '', email: '', phone: '', service: query.get('package') ?? '', concern: query.get('concern') ?? '', date: '', method: query.get('method') === 'Zoom call' ? 'Zoom call' : 'Video consultation', website: '' });
  const [status, setStatus] = useState<{ kind: 'idle' | 'loading' | 'success' | 'error'; message: string }>({ kind: 'idle', message: '' });
  const [attempted, setAttempted] = useState(false);
  const errors: Record<string, string> = {};
  if (attempted) { if (!form.name.trim()) errors.name = 'Please enter your name.'; if (!/^\S+@\S+\.\S+$/.test(form.email)) errors.email = 'Enter a valid email address.'; if (!form.service) errors.service = 'Choose a service or package.'; if (!form.concern.trim()) errors.concern = 'Please share a brief description.'; }
  const update = (key: string, value: string) => { setForm(previous => ({ ...previous, [key]: value })); if (status.kind !== 'idle') setStatus({ kind: 'idle', message: '' }); };
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setAttempted(true); const requiredMissing = !form.name.trim() || !/^\S+@\S+\.\S+$/.test(form.email) || !form.service || !form.concern.trim();
    if (requiredMissing) { setStatus({ kind: 'error', message: 'Please correct the highlighted fields before sending.' }); return; }
    setStatus({ kind: 'loading', message: 'Sending your request securely…' });
    try {
      const response = await fetch('/api/contact.php', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(form) });
      const responseText = await response.text();
      let result: { ok?: boolean; message?: string };
      try { result = JSON.parse(responseText); } catch { throw new Error('The enquiry service is not configured on this hosting account yet. Please try again after PHP form delivery is activated.'); }
      if (!response.ok || !result.ok) throw new Error(result.message || 'We could not send your request. Please try again later.');
      setStatus({ kind: 'success', message: result.message || 'Thank you. Your consultation request has been sent.' }); setAttempted(false); setForm({ name: '', business: '', email: '', phone: '', service: '', concern: '', date: '', method: 'Video consultation', website: '' });
    } catch (error) {
      setStatus({ kind: 'error', message: error instanceof Error ? error.message : 'Enquiry delivery is not available. Please try again later.' });
    }
  }
  const emailReady = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.businessEmail);
  const zoomUrl = config.zoomBookingUrl.startsWith('https://') ? config.zoomBookingUrl : '';
  return <><Meta title="Contact & book a consultation" description="Book a confidential 15-minute video consultation with Nestshield Cybersecurity."/><PageHero label="CONTACT & CONSULTATION" title="Let's talk about what matters." text="Begin with a confidential 15-minute video consultation. We will listen, clarify your concern and explain potential next steps—without pressure." dark/><section className="section-pad contact-section"><div className="container contact-layout"><div className="contact-intro"><Eyebrow>BOOK A CONSULTATION</Eyebrow><h2>A clear first step.<br/><em>No obligation to proceed.</em></h2><Photo className="contact-photo" src="/images/contact-support.jpg" alt="A smiling support consultant wearing a headset in his office" ratio="1 / 1" focus="50% 35%" /><p>Complete the form and, once official enquiry delivery is configured, your request will be sent securely to the business. Please do not include passwords, payment codes or sensitive information.</p><div className="contact-facts"><div><span><Clock3/></span><div><b>15 minutes</b><small>Initial consultation</small></div></div><div><span><ShieldCheck/></span><div><b>Private by design</b><small>We request only what is needed</small></div></div></div><div className="contact-email-box"><span className="mono-label">BUSINESS EMAIL</span><p>{emailReady ? <a href={`mailto:${config.businessEmail}`}>{config.businessEmail}</a> : 'Official email address to be configured'}</p></div><div className="zoom-info"><span className="zoom-symbol">Z</span><p><b>Prefer Zoom?</b><br/>{zoomUrl ? <>Use the <a href={zoomUrl} target="_blank" rel="noopener noreferrer">official Zoom booking link</a>, or select Zoom call in the form.</> : 'Select Zoom call in the form. An official meeting link will be shared after your request is reviewed.'}</p></div></div><form className="booking-form" onSubmit={submit} noValidate><div className="form-heading"><span className="mono-label">CONSULTATION REQUEST</span><p>Fields marked with * are required.</p></div><div className="form-grid"><Field label="Full name" required error={errors.name}><input autoComplete="name" value={form.name} onChange={e => update('name', e.target.value)} aria-invalid={!!errors.name}/></Field><Field label="Business or organization"><input autoComplete="organization" value={form.business} onChange={e => update('business', e.target.value)}/></Field><Field label="Email address" required error={errors.email}><input type="email" autoComplete="email" value={form.email} onChange={e => update('email', e.target.value)} aria-invalid={!!errors.email}/></Field><Field label="Phone number"><input type="tel" autoComplete="tel" value={form.phone} onChange={e => update('phone', e.target.value)}/></Field><Field label="Service or package of interest" required error={errors.service}><select value={form.service} onChange={e => update('service', e.target.value)} aria-invalid={!!errors.service}><option value="">Select an option</option>{packages.map(item => <option key={item.title} value={item.title}>{item.title} — {item.name} (${item.price})</option>)}<option value="General cybersecurity or IT support">General cybersecurity or IT support</option><option value="Not sure yet">Not sure yet</option></select></Field><Field label="Preferred consultation date"><input type="date" min={new Date().toISOString().split('T')[0]} value={form.date} onChange={e => update('date', e.target.value)}/></Field><Field label="Preferred consultation method" className="field-full"><div className="method-options"><label className={form.method === 'Video consultation' ? 'method-option active' : 'method-option'}><input type="radio" name="method" value="Video consultation" checked={form.method === 'Video consultation'} onChange={e => update('method', e.target.value)}/><span className="radio-look"/><span><b>Video consultation</b><small>15-minute initial conversation</small></span></label><label className={form.method === 'Zoom call' ? 'method-option active' : 'method-option'}><input type="radio" name="method" value="Zoom call" checked={form.method === 'Zoom call'} onChange={e => update('method', e.target.value)}/><span className="radio-look"/><span><b>Zoom call</b><small>Official link shared after review</small></span></label></div></Field><Field label="Briefly describe your concern" required error={errors.concern} className="field-full"><textarea rows={4} maxLength={2000} placeholder="Share a little context. Please do not include passwords or payment details." value={form.concern} onChange={e => update('concern', e.target.value)} aria-invalid={!!errors.concern}/><small className="char-count">{form.concern.length}/2000</small></Field><div className="honeypot" aria-hidden="true"><label>Leave this field empty<input tabIndex={-1} autoComplete="off" value={form.website} onChange={e => update('website', e.target.value)}/></label></div><div className="form-submit field-full"><button className="button button-primary" disabled={status.kind === 'loading'}>{status.kind === 'loading' ? 'Sending request…' : 'Send consultation request'}{status.kind !== 'loading' && <ArrowRight size={16}/>}</button><p>By submitting, you agree that we may use these details to respond to your enquiry.</p>{status.message && <div role="status" aria-live="polite" className={`form-status status-${status.kind}`}>{status.kind === 'success' ? <Check size={18}/> : status.kind === 'loading' ? <span className="spinner"/> : <Shield size={18}/>}<span>{status.message}</span></div>}</div></div></form></div></section><section className="contact-reassurance"><div className="container"><ShieldCheck/><p>Remote technical assistance is never automatic. Your approval is required, and access is limited to agreed work. We never request banking passwords or payment authentication codes.</p></div></section></>;
}
function Field({ label, required, error, className = '', children }: { label: string; required?: boolean; error?: string; className?: string; children: ReactNode }) {
  const id = useId();
  const group = isValidElement(children) && typeof children.type === 'string' && children.type === 'div';
  const control = isValidElement(children)
    ? cloneElement(children as ReactElement<{ id?: string; role?: string; 'aria-labelledby'?: string }>, group ? { id, role: 'group', 'aria-labelledby': `${id}-label` } : { id })
    : children;
  return <div className={`field ${className}`}><label id={`${id}-label`} htmlFor={group ? undefined : id}>{label}{required && <span> *</span>}</label>{control}{error && <small className="field-error">{error}</small>}</div>;
}

function Legal({ privacy = false }: { privacy?: boolean }) {
  const title = privacy ? 'Privacy policy' : 'Terms of service';
  return <><Meta title={title} description={`${title} for Nestshield Cybersecurity.`}/><PageHero label="IMPORTANT INFORMATION" title={title} text="Clear information about how this website and consultation process are intended to work."/><section className="section-pad legal-page"><div className="container legal-copy"><p className="legal-note"><b>Publication note:</b> This general website notice should be reviewed and adapted to your actual business practices and applicable law before launch.</p>{privacy ? <><h2>Information you provide</h2><p>The consultation form requests contact details and a short description of your concern so that Nestshield Cybersecurity can review and respond to your enquiry. Do not submit passwords, payment authentication codes or sensitive information that is not needed to describe the request.</p><h2>How information is used</h2><p>Information submitted through the form is intended to be used to assess, respond to and follow up on your consultation request. It should not be used for unrelated purposes. Access to submitted information should be restricted to people who need it to handle the enquiry.</p><h2>Retention and security</h2><p>Enquiry information should be retained only as long as necessary for the enquiry and any agreed services, subject to applicable record-keeping requirements. Appropriate technical and organizational safeguards should be used, while recognizing no online transmission or storage method can be guaranteed completely secure.</p><h2>Third-party services</h2><p>This website loads web fonts from Google Fonts. The hosting provider and email delivery service may process technical information when the website or its form is used. Review provider terms and configure the form delivery service before launch.</p><h2>Your questions</h2><p>For privacy questions or requests concerning information submitted through this website, use the official business contact details once they have been configured and published.</p></> : <><h2>Website information</h2><p>Website information is provided to describe cybersecurity and IT support services. It is not a guarantee of security outcomes and is not a substitute for a technical assessment or professional advice appropriate to your specific circumstances.</p><h2>Service scope and pricing</h2><p>Listed package prices are in USD. All services are subject to an initial assessment, agreed scope and confirmation of technical requirements. No work should proceed until the specific service, scope, applicable price and expectations have been discussed and agreed.</p><h2>Authorization and access</h2><p>Any access to a device, account or network must be authorized by the relevant owner or administrator and limited to the work agreed. Clients retain control of their devices and accounts. Do not share banking passwords, payment authentication codes or other unnecessary confidential information.</p><h2>No guarantee of complete protection</h2><p>No cybersecurity service can guarantee complete protection against every attack, threat, loss or interruption. Recommendations are intended to support risk reduction and ongoing improvement, not to eliminate all risk.</p><h2>Website availability</h2><p>Website features and enquiry delivery depend on hosting and communication services. A form request is only confirmed as sent when the website displays a successful delivery confirmation. Do not rely on an unconfirmed web submission for urgent matters.</p><h2>Questions</h2><p>For service terms applicable to a particular engagement, obtain and review the written scope and agreement provided before work begins.</p></>}</div></section><CTA title="Need to clarify something?" text="Talk through your questions before you decide whether to proceed."/></>;
}
function NotFound() { return <><PageHero label="404 / PAGE NOT FOUND" title="This page isn't here." text="The link may have changed, or the address may be incorrect."/><section className="not-found"><Link to="/" className="button button-primary">Return to home <ArrowRight size={16}/></Link></section></>; }

export default function App() {
  const [config, setConfig] = useState<Config>({ businessName: 'Nestshield Cybersecurity', businessEmail: '', zoomBookingUrl: '' });
  useEffect(() => { fetch('/business-config.json').then(response => response.ok ? response.json() : Promise.reject()).then((data: Partial<Config>) => setConfig({ businessName: data.businessName || 'Nestshield Cybersecurity', businessEmail: data.businessEmail || '', zoomBookingUrl: data.zoomBookingUrl || '' })).catch(() => { /* Preserve safe placeholders if deployment config cannot be loaded. */ }); }, []);
  return <ConfigContext.Provider value={config}><Layout><Routes><Route path="/" element={<Home/>}/><Route path="/about" element={<About/>}/><Route path="/services" element={<Services/>}/><Route path="/packages" element={<Packages/>}/><Route path="/reviews" element={<Reviews/>}/><Route path="/approach" element={<Approach/>}/><Route path="/contact" element={<Contact/>}/><Route path="/privacy" element={<Legal privacy/>}/><Route path="/terms" element={<Legal/>}/><Route path="*" element={<NotFound/>}/></Routes></Layout></ConfigContext.Provider>;
}
